import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

import snapshot from "./cows-snapshot.json" with { type: "json" };

const directory = new URL("../src/cows/", import.meta.url);
const namePattern = /^[a-z][a-z.-]*$/;
const banner = `// SPDX-FileCopyrightText: 2026 AFCMS <afcm.contact@gmail.com>
// SPDX-License-Identifier: MIT

// Generated by scripts/generate-cows.ts from the verified snapshot. Do not edit.`;

/**
 * Verifies every artwork and notice hash before returning the sorted bundled names.
 */
async function verifiedNames(): Promise<string[]> {
  const names: string[] = [];

  for (const [path, expectedHash] of Object.entries(snapshot.files)) {
    const file = path.split("/").at(-1)!;
    const data = await readFile(new URL(file, directory));
    const actualHash = createHash("sha1")
      .update(`blob ${data.length}\0`)
      .update(data)
      .digest("hex");

    if (actualHash !== expectedHash) {
      throw new Error(`Artwork integrity mismatch: ${file}`);
    }
    if (file.endsWith(".cow")) {
      names.push(file.slice(0, -4));
    }
  }

  if (names.length !== 54 || names.some((name) => !namePattern.test(name))) {
    throw new Error("Unexpected bundled cow collection");
  }

  return names.toSorted();
}

/**
 * Emits one reusable compiled cow while preserving its native text import.
 */
function cowModule(name: string): string {
  return `${banner}
import source from "./${name}.cow" with { type: "text" };
import { compileCow } from "../compiler.ts";

const cow = /* @__PURE__ */ compileCow(source, "${name}.cow");
export default cow;
`;
}

/**
 * Emits readable names and literal lazy imports without importing artwork eagerly.
 */
function catalogModule(names: readonly string[]): string {
  const nameEntries = names.map((name) => `  ${JSON.stringify(name)},`).join("\n");
  const loaderEntries = names
    .map((name) => {
      const key = JSON.stringify(name);
      return `    ${key}: () => import("./cows/${name}.ts"),`;
    })
    .join("\n");

  return `${banner}
import type { Cow } from "./types.ts";

export const cowNames = /* @__PURE__ */ Object.freeze([
${nameEntries}
] as const);

export type CowName = (typeof cowNames)[number];

export const loaders: Readonly<Record<CowName, () => Promise<{ default: Cow }>>> =
  /* @__PURE__ */ Object.freeze({
${loaderEntries}
  });
`;
}

/**
 * Regenerates cow entry points and the catalog from the complete verified snapshot.
 */
export async function generateCows(): Promise<void> {
  const names = await verifiedNames();

  for (const name of names) {
    const destination = new URL(`${name}.ts`, directory);
    await writeFile(destination, cowModule(name));
  }

  const catalog = new URL("../catalog.ts", directory);
  await writeFile(catalog, catalogModule(names));
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await generateCows();
}
